let cart = [];

const cartBtn = document.getElementById('cartBtn');
const cartModal = document.getElementById('cartModal');
const closeBtn = document.querySelector('.close-btn');
const cartCountElement = document.querySelector('.cart-count');
const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
const wishlistButtons = document.querySelectorAll('.wishlist-btn');

// Product data
const products = {
    1: { name: 'Premium Minimalist Jacket', price: 249.00 },
    2: { name: 'Timeless Leather Belt', price: 159.00 },
    3: { name: 'Designer Leather Shoes', price: 329.00 },
    4: { name: 'Minimalist Watch Collection', price: 449.00 }
};

// Add to cart functionality
addToCartButtons.forEach(button => {
    button.addEventListener('click', function() {
        const productCard = this.closest('.product-card');
        const productId = productCard.getAttribute('data-product-id');
        const product = products[productId];

        if (product) {
            const existingItem = cart.find(item => item.id === productId);
            if (existingItem) {
                existingItem.quantity += 1;
            } else {
                cart.push({
                    id: productId,
                    name: product.name,
                    price: product.price,
                    quantity: 1
                });
            }

            updateCartUI();
            showNotification(`${product.name} added to cart!`);
        }
    });
});

// Wishlist functionality
wishlistButtons.forEach(button => {
    button.addEventListener('click', function() {
        this.classList.toggle('active');
        const isActive = this.classList.contains('active');
        this.textContent = isActive ? '♥' : '♡';
    });
});

// Update cart UI
function updateCartUI() {
    cartCountElement.textContent = cart.reduce((sum, item) => sum + item.quantity, 0);
    renderCartItems();
}

// Render cart items
function renderCartItems() {
    const cartItemsContainer = document.getElementById('cartItems');
    const cartSummary = document.getElementById('cartSummary');

    if (cart.length === 0) {
        cartItemsContainer.innerHTML = '<p class="empty-cart">Your cart is empty</p>';
        cartSummary.style.display = 'none';
        return;
    }

    cartItemsContainer.innerHTML = cart.map(item => `
        <div class="cart-item">
            <div class="cart-item-name">
                <p>${item.name}</p>
                <small>Qty: ${item.quantity}</small>
            </div>
            <div>
                <span class="cart-item-price">$${(item.price * item.quantity).toFixed(2)}</span>
                <button class="remove-item" data-product-id="${item.id}">✕</button>
            </div>
        </div>
    `).join('');

    // Add remove item listeners
    document.querySelectorAll('.remove-item').forEach(btn => {
        btn.addEventListener('click', function() {
            const productId = this.getAttribute('data-product-id');
            cart = cart.filter(item => item.id !== productId);
            updateCartUI();
        });
    });

    updateCartSummary();
    cartSummary.style.display = 'block';
}

// Update cart summary
function updateCartSummary() {
    const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    const shipping = subtotal > 200 ? 0 : 10;
    const total = subtotal + shipping;

    document.getElementById('subtotal').textContent = `$${subtotal.toFixed(2)}`;
    document.getElementById('shipping').textContent = shipping === 0 ? 'FREE' : `$${shipping.toFixed(2)}`;
    document.getElementById('total').textContent = `$${total.toFixed(2)}`;
}

// Cart modal functionality
cartBtn.addEventListener('click', function() {
    cartModal.classList.add('active');
});

closeBtn.addEventListener('click', function() {
    cartModal.classList.remove('active');
});

cartModal.addEventListener('click', function(e) {
    if (e.target === cartModal) {
        cartModal.classList.remove('active');
    }
});

// Newsletter subscription
const newsletterForm = document.getElementById('newsletterForm');
newsletterForm.addEventListener('submit', function(e) {
    e.preventDefault();
    const email = this.querySelector('input[type="email"]').value;
    showNotification(`Welcome! We'll send exclusive offers to ${email}`);
    this.reset();
});

// Smooth scrolling
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
        const href = this.getAttribute('href');
