+            const productId = this.getAttribute('data-product-id');
+            cart = cart.filter(item => item.id !== productId);
+            updateCartUI();
+        });
+    });
+
+    updateCartSummary();
+    cartSummary.style.display = 'block';
+}
+
+// Update cart summary
+function updateCartSummary() {
