+        const parts = time.split(':').map(Number);
+        let [hours, minutes, seconds] = parts;
+
+        setInterval(() => {
+            seconds--;
+            if (seconds < 0) {
+                seconds = 59;
+                minutes--;
+                if (minutes < 0) {
+                    minutes = 59;
+                    hours--;
